	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Season
	 */
		public Season createSeason( CreateSeasonCommand command ) {

		Season entity = new Season();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setSeasonId( command.getSeasonId() );
            entity.setName( command.getName() );
            entity.setYear( command.getYear() );
            entity.setPeriod( command.getPeriod() );
            entity.setSeasonType( command.getSeasonType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Season {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateSeasonCommand
	 * @return		Season
	 */
	public Season updateSeason( UpdateSeasonCommand command ) {

		Season entity = new Season();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setSeasonId( command.getSeasonId() );
            entity.setName( command.getName() );
            entity.setYear( command.getYear() );
            entity.setPeriod( command.getPeriod() );
            entity.setFarm( command.getFarm() );
            entity.setPlantingPlans( command.getPlantingPlans() );
            entity.setIrrigationEvents( command.getIrrigationEvents() );
            entity.setApplications( command.getApplications() );
            entity.setHarvests( command.getHarvests() );
            entity.setScoutingFindings( command.getScoutingFindings() );
            entity.setInsurancePolicies( command.getInsurancePolicies() );
            entity.setSeasonType( command.getSeasonType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Season {0} ", entity.toString() );

		return entity;
	}

